import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export class BookStorage {
  constructor(filePath) {
    this.filePath = filePath || process.env.DATA_FILE || path.join(process.cwd(), 'data', 'books.json');
    this.ensureFile();
  }

  ensureFile() {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    if (!fs.existsSync(this.filePath)) {
      fs.writeFileSync(this.filePath, JSON.stringify([], null, 2), 'utf8');
    }
  }

  _readAll() {
    try {
      if (!fs.existsSync(this.filePath)) {
        return [];
      }
      const raw = fs.readFileSync(this.filePath, 'utf8');
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (err) {
      console.error('Error reading books file:', err);
      return [];
    }
  }

  _writeAll(books) {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    // Write atomically via temp file to avoid partial writes
    const tempFile = `${this.filePath}.${crypto.randomUUID()}.tmp`;
    fs.writeFileSync(tempFile, JSON.stringify(books, null, 2), 'utf8');
    fs.renameSync(tempFile, this.filePath);
  }

  getAll() {
    return this._readAll();
  }

  getById(id) {
    const books = this._readAll();
    return books.find((b) => b.id === id) || null;
  }

  getCurrentlyReading() {
    return this._readAll().filter((b) => b.status === 'reading');
  }

  getFinished() {
    return this._readAll().filter((b) => b.status === 'finished');
  }

  add({ title, author, notes, status }) {
    const cleanTitle = (title || '').trim();
    if (!cleanTitle) {
      throw new Error('Title is required');
    }

    const cleanAuthor = (author || '').trim();
    const cleanNotes = (notes || '').trim();
    const bookStatus = status === 'finished' ? 'finished' : 'reading';
    const now = new Date().toISOString();

    const newBook = {
      id: crypto.randomUUID(),
      title: cleanTitle,
      author: cleanAuthor,
      notes: cleanNotes,
      status: bookStatus,
      createdAt: now,
      finishedAt: bookStatus === 'finished' ? now : null,
    };

    const books = this._readAll();
    books.unshift(newBook);
    this._writeAll(books);
    return newBook;
  }

  markAsFinished(id) {
    const books = this._readAll();
    const book = books.find((b) => b.id === id);
    if (!book) {
      return null;
    }

    book.status = 'finished';
    book.finishedAt = new Date().toISOString();
    this._writeAll(books);
    return book;
  }

  markAsReading(id) {
    const books = this._readAll();
    const book = books.find((b) => b.id === id);
    if (!book) {
      return null;
    }

    book.status = 'reading';
    book.finishedAt = null;
    this._writeAll(books);
    return book;
  }

  delete(id) {
    const books = this._readAll();
    const index = books.findIndex((b) => b.id === id);
    if (index === -1) {
      return false;
    }
    books.splice(index, 1);
    this._writeAll(books);
    return true;
  }
}

export const defaultStorage = new BookStorage();

/* Reset and Base Styles */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-serif: "Iowan Old Style", "Palatino Linotype", "URW Palladio L", P052, serif, "Georgia";

  --bg-page: #fbfaf8;
  --bg-card: #ffffff;
  --text-main: #262626;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --border-light: #f3f4f6;

  --color-primary: #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-primary-light: #eff6ff;

  --badge-reading-bg: #fef3c7;
  --badge-reading-text: #92400e;
  --badge-reading-border: #fde68a;

  --badge-finished-bg: #dcfce7;
  --badge-finished-text: #166534;
  --badge-finished-border: #bbf7d0;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --radius: 8px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.container {
  width: 100%;
  max-width: 1040px;
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* Header */
.site-header {
  background-color: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 0;
  margin-bottom: 2rem;
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  text-decoration: none;
  color: var(--text-main);
}

.brand-icon {
  font-size: 1.5rem;
}

.brand-title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.header-tagline {
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* Dashboard Layout */
.dashboard-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  .dashboard-grid {
    grid-template-columns: 3fr 2fr;
    align-items: start;
  }
}

.main-column {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.side-column {
  position: sticky;
  top: 1.5rem;
}

/* Section Cards */
.section-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
}

.section-header {
  margin-bottom: 1.25rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--border-light);
}

.section-title-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.section-header h2 {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text-main);
}

.count-pill {
  font-size: 0.75rem;
  font-weight: 600;
  background-color: var(--border-light);
  color: var(--text-muted);
  padding: 0.2rem 0.55rem;
  border-radius: 9999px;
}

/* Book List & Cards */
.book-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.book-card {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 1.1rem 1.25rem;
  background: var(--bg-card);
  transition: box-shadow 0.15s ease, border-color 0.15s ease;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.book-card:hover {
  border-color: #cbd5e1;
  box-shadow: var(--shadow-md);
}

.book-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.75rem;
}

.book-title {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1.3;
}

.book-title a {
  color: var(--text-main);
  text-decoration: none;
}

.book-title a:hover {
  color: var(--color-primary);
  text-decoration: underline;
}

.book-author {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-top: 0.2rem;
}

.book-notes-preview {
  margin-top: 0.5rem;
  font-size: 0.875rem;
  color: #4b5563;
  line-height: 1.45;
  background: #f9fafb;
  padding: 0.5rem 0.75rem;
  border-radius: 4px;
  border-left: 3px solid #d1d5db;
}

.book-card-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding-top: 0.5rem;
  border-top: 1px solid var(--border-light);
  margin-top: 0.25rem;
}

/* Badges */
.badge {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  white-space: nowrap;
}

.badge-lg {
  font-size: 0.825rem;
  padding: 0.25rem 0.65rem;
  margin-bottom: 0.75rem;
}

.badge-reading {
  background-color: var(--badge-reading-bg);
  color: var(--badge-reading-text);
  border: 1px solid var(--badge-reading-border);
}

.badge-finished {
  background-color: var(--badge-finished-bg);
  color: var(--badge-finished-text);
  border: 1px solid var(--badge-finished-border);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0.55rem 1rem;
  border-radius: 6px;
  border: 1px solid transparent;
  cursor: pointer;
  text-decoration: none;
  transition: all 0.15s ease;
  font-family: inherit;
}

.btn-sm {
  font-size: 0.8rem;
  padding: 0.35rem 0.65rem;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
}

.btn-secondary {
  background-color: #ffffff;
  color: var(--text-main);
  border-color: var(--border-color);
}

.btn-secondary:hover {
  background-color: #f9fafb;
  border-color: #cbd5e1;
}

.btn-ghost {
  background-color: transparent;
  color: var(--text-muted);
  border-color: var(--border-color);
}

.btn-ghost:hover {
  background-color: #f9fafb;
  color: var(--text-main);
}

.btn-link {
  background: none;
  border: none;
  color: var(--color-primary);
  padding: 0;
}

.btn-link:hover {
  text-decoration: underline;
}

.btn-danger-ghost {
  background-color: transparent;
  color: #dc2626;
  border: 1px solid #fecaca;
}

.btn-danger-ghost:hover {
  background-color: #fef2f2;
}

.btn-block {
  width: 100%;
}

/* Forms */
.book-form {
  display: flex;
  flex-direction: column;
  gap: 1.1rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.form-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: #374151;
}

.required {
  color: #dc2626;
}

.form-group input,
.form-group select,
.form-group textarea {
  font-family: inherit;
  font-size: 0.925rem;
  padding: 0.55rem 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background-color: #ffffff;
  color: var(--text-main);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

/* Empty States */
.empty-state {
  text-align: center;
  padding: 2.5rem 1rem;
  background-color: #f9fafb;
  border-radius: 6px;
  border: 1px dashed var(--border-color);
}

.empty-state p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.empty-hint {
  display: block;
  font-size: 0.825rem;
  color: #9ca3af;
  margin-top: 0.25rem;
}

/* Alerts */
.alert {
  padding: 0.75rem 1rem;
  border-radius: 6px;
  margin-bottom: 1.5rem;
  font-size: 0.875rem;
}

.alert-error {
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
}

/* Book Detail Page */
.book-detail-wrapper {
  max-width: 720px;
  margin: 0 auto;
}

.breadcrumb {
  margin-bottom: 1rem;
}

.back-link {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 500;
}

.back-link:hover {
  color: var(--color-primary);
  text-decoration: underline;
}

.book-detail-card {
  padding: 2rem;
}

.book-detail-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  flex-wrap: wrap;
}

.book-detail-meta {
  flex: 1;
}

.book-detail-title {
  font-family: var(--font-serif);
  font-size: 1.85rem;
  line-height: 1.25;
  color: var(--text-main);
  margin-bottom: 0.25rem;
}

.book-detail-author {
  font-size: 1.1rem;
  color: var(--text-muted);
}

.divider {
  border: none;
  border-top: 1px solid var(--border-color);
  margin: 1.5rem 0;
}

.notes-heading {
  font-size: 1.15rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
  color: var(--text-main);
}

.notes-box {
  background: #fdfdfd;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 1.25rem;
}

.notes-text {
  font-family: inherit;
  white-space: pre-wrap;
  word-wrap: break-word;
  font-size: 0.95rem;
  line-height: 1.6;
  color: #334155;
}

/* Share Section */
.share-section {
  background-color: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 1rem 1.25rem;
}

.share-heading {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.share-description {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}

.share-input-group {
  display: flex;
  gap: 0.5rem;
}

.share-input {
  flex: 1;
  font-family: monospace;
  font-size: 0.85rem;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background-color: #ffffff;
  color: #475569;
}

.copy-feedback {
  margin-top: 0.5rem;
  font-size: 0.8rem;
  color: #16a34a;
  font-weight: 500;
}

.book-footer-actions {
  display: flex;
  justify-content: flex-end;
}

/* Footer */
.site-footer {
  margin-top: auto;
  border-top: 1px solid var(--border-color);
  padding: 1.5rem 0;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.825rem;
