import express from 'express';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { defaultStorage } from './storage.js';
import { renderHomePage, renderBookPage, renderNotFoundPage } from './views.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export function createApp(storage = defaultStorage) {
  const app = express();

  app.use(express.urlencoded({ extended: false }));
  app.use(express.json());
  app.use(express.static(path.join(__dirname, '..', 'public')));

  // Helper to check if client prefers JSON
  const isJsonRequest = (req) => {
    return req.is('json') || (req.headers.accept && req.headers.accept.includes('application/json'));
  };

  // Home page: shows currently reading and finished books
  app.get('/', (req, res) => {
    const readingBooks = storage.getCurrentlyReading();
    const finishedBooks = storage.getFinished();

    if (isJsonRequest(req)) {
      return res.json({
        currentlyReading: readingBooks,
        finished: finishedBooks,
      });
    }

    const html = renderHomePage({
      readingBooks,
      finishedBooks,
      error: req.query.error,
    });
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(html);
  });

  // Add book
  app.post('/books', (req, res) => {
    const { title, author, notes, status } = req.body;
    try {
      const book = storage.add({ title, author, notes, status });
      if (isJsonRequest(req)) {
        return res.status(201).json(book);
      }
      res.redirect('/');
    } catch (err) {
      if (isJsonRequest(req)) {
        return res.status(400).json({ error: err.message });
      }
      const readingBooks = storage.getCurrentlyReading();
      const finishedBooks = storage.getFinished();
      const html = renderHomePage({
        readingBooks,
        finishedBooks,
        error: err.message,
      });
      res.status(400).send(html);
    }
  });

  // Single book page
  app.get('/books/:id', (req, res) => {
    const book = storage.getById(req.params.id);
    if (!book) {
      if (isJsonRequest(req)) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.status(404).setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.send(renderNotFoundPage());
    }

    if (isJsonRequest(req)) {
      return res.json(book);
    }

    const hostUrl = `${req.protocol}://${req.get('host')}`;
    const html = renderBookPage({ book, hostUrl });
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(html);
  });

  // Mark book as finished
  app.post('/books/:id/finish', (req, res) => {
    const book = storage.markAsFinished(req.params.id);
    if (!book) {
      if (isJsonRequest(req)) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.status(404).setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.send(renderNotFoundPage());
    }

    if (isJsonRequest(req)) {
      return res.json(book);
    }

    const referrer = req.get('Referrer');
    if (referrer && (referrer.includes(`/books/${req.params.id}`) || referrer.endsWith('/'))) {
      res.redirect(referrer);
    } else {
      res.redirect('/');
    }
  });

  // Mark book as reading
  app.post('/books/:id/reading', (req, res) => {
    const book = storage.markAsReading(req.params.id);
    if (!book) {
      if (isJsonRequest(req)) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.status(404).setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.send(renderNotFoundPage());
    }

    if (isJsonRequest(req)) {
      return res.json(book);
    }

    const referrer = req.get('Referrer');
    if (referrer && referrer.includes(`/books/${req.params.id}`)) {
      res.redirect(referrer);
    } else {
      res.redirect('/');
    }
  });

  // Delete book
  app.post('/books/:id/delete', (req, res) => {
    const success = storage.delete(req.params.id);
    if (!success) {
      if (isJsonRequest(req)) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.status(404).setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.send(renderNotFoundPage());
    }

    if (isJsonRequest(req)) {
      return res.json({ success: true });
    }

    res.redirect('/');
  });

  // API endpoints for direct programmatic consumption
  app.get('/api/books', (req, res) => {
    res.json(storage.getAll());
  });

  app.post('/api/books', (req, res) => {
    const { title, author, notes, status } = req.body;
    try {
      const book = storage.add({ title, author, notes, status });
      res.status(201).json(book);
    } catch (err) {
      res.status(400).json({ error: err.message });
    }
  });

  app.get('/api/books/:id', (req, res) => {
    const book = storage.getById(req.params.id);
    if (!book) {
      return res.status(404).json({ error: 'Book not found' });
    }
    res.json(book);
  });

  app.post('/api/books/:id/finish', (req, res) => {
    const book = storage.markAsFinished(req.params.id);
    if (!book) {
      return res.status(404).json({ error: 'Book not found' });
    }
    res.json(book);
  });

  return app;
}

import { createApp } from './src/app.js';

const PORT = process.env.PORT || 3000;
const app = createApp();

const server = app.listen(PORT, () => {
  console.log(`Reading Log app running at http://localhost:${PORT}`);
});

process.on('SIGINT', () => {
  server.close(() => process.exit(0));
});

process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
});

