import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import request from 'supertest';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createApp } from '../src/app.js';
import { BookStorage } from '../src/storage.js';

describe('Book Tracking App', () => {
  let tmpDir;
  let testFilePath;
  let storage;
  let app;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'book-test-'));
    testFilePath = path.join(tmpDir, 'books.json');
    storage = new BookStorage(testFilePath);
    app = createApp(storage);
  });

  afterEach(() => {
    try {
      fs.rmSync(tmpDir, { recursive: true, force: true });
    } catch {
      // ignore
    }
  });

  it('renders home page with empty reading and finished sections', async () => {
    const res = await request(app).get('/');
    expect(res.status).toBe(200);
    expect(res.text).toContain('Currently Reading');
    expect(res.text).toContain('Finished');
    expect(res.text).toContain('You aren&#39;t reading any books right now.');
    expect(res.text).toContain('No finished books yet.');
  });

  it('adds a book from form submission and saves to JSON file', async () => {
    const res = await request(app)
      .post('/books')
      .type('form')
      .send({
        title: 'Project Hail Mary',
        author: 'Andy Weir',
        notes: 'Fascinating space survival story.\nLoved Rocky!',
        status: 'reading',
      });

    expect(res.status).toBe(302);
